/**
 * @beta
 * 用于缩小一组声音定义范围的条件。每个字段都是可选的，并且仅在定义时施加约束；一个定义必须满足所有定义的字段才能通过。
 */
export interface SoundDefinitionFilter {
    /**
     * @remarks
     * 要与定义中的 music_info.artist 匹配的艺术家名称。比较时不区分大小写。当定义为非空数组时，定义仅在其声明的艺术家与提供的值之一匹配时通过。当未定义时，不施加艺术家约束。
     *
     */
    artists?: string[];
    /**
     * @remarks
     * 要与定义中的 music_info.genres 匹配的流派。比较时不区分大小写。当定义为非空数组时，定义仅在其声明的流派中至少有一个与提供的值之一匹配时通过。当未定义时，不施加流派约束。
     *
     */
    genres?: string[];
    /**
     * @remarks
     * 以秒为单位的上限，包含边界。当定义时，持续时间更长的定义以及没有声明持续时间的定义将被排除。当未定义时，不施加上限。
     *
     */
    maxDuration?: number;
    /**
     * @remarks
     * 以秒为单位的下限，包含边界。当定义时，持续时间更短的定义以及没有声明持续时间的定义将被排除。当未定义时，不施加下限。
     *
     */
    minDuration?: number;
    /**
     * @remarks
     * 要与定义中的 music_info.moods 匹配的情绪。比较时不区分大小写。当定义为非空数组时，定义仅在其声明的情绪中至少有一个与提供的值之一匹配时通过。当未定义时，不施加情绪约束。
     *
     */
    moods?: string[];
    /**
     * @remarks
     * 要与定义中的标签匹配的标签约束。标签名称和值的比较不区分大小写。当定义为非空记录时，对于每个具有非空值数组的条目，定义仅当标签名称存在于定义上且至少有一个匹配值时才通过。当未定义时，不施加标签约束。
     *
     */
    tags?: Record<string, string[]>;
    /**
     * @remarks
     * 要与定义中的 music_info.title 匹配的标题。比较时不区分大小写。当定义为非空数组时，定义仅在其声明的标题与提供的值之一匹配时通过。当未定义时，不施加标题约束。
     *
     */
    titles?: string[];
}